const body = $json.body ?? $json;
const clean = (v, max = 4000) => { const s = String(v ?? '').trim(); return s ? s.slice(0, max) : null; };
const name = clean(body.name, 160);
const email = clean(body.email, 320)?.toLowerCase() ?? null;
const emailOk = !!email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const service = clean(body.service, 160);
const postcode = clean(body.postcode, 32);
const urgencyRaw = String(body.urgency ?? '').trim().toLowerCase();
const allowedUrgencies = ['emergency', 'this_week', 'flexible'];
const urgency = allowedUrgencies.includes(urgencyRaw) ? urgencyRaw : 'unknown';
const submissionId = clean(body.submission_id, 120) || (globalThis.crypto?.randomUUID?.() ?? 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 3 | 8)).toString(16); }));
const rawPhone = clean(body.phone, 40);
let phone = null;
if (rawPhone) {
  const digits = rawPhone.replace(/[^0-9+]/g, '');
  if (/^\+61[0-9]{9}$/.test(digits)) phone = digits;
  else if (/^61[0-9]{9}$/.test(digits)) phone = '+' + digits;
  else if (/^0[0-9]{9}$/.test(digits)) phone = '+61' + digits.slice(1);
}
const propertyType = clean(body.property_type, 100);
const message = String(body.message ?? '').slice(0, 4000);
const honeypot = String(body.honeypot ?? '').slice(0, 500);
const consent = body.consent === true || body.consent === 'true';
const issues = [];
if (!name) issues.push('Enter your name.');
if (!emailOk) issues.push('Enter a valid email address.');
if (!service) issues.push('Choose the work you need.');
if (!postcode) issues.push('Enter your postcode.');
if (!allowedUrgencies.includes(urgencyRaw)) issues.push('Choose when you need help.');
if (!consent) issues.push('Consent is required to process this request.');
const receivedAt = new Date().toISOString();
const rawPayload = { name, email, phone: rawPhone, service, postcode, urgency: urgencyRaw, property_type: propertyType, message, honeypot, consent };
return [{ json: { valid: issues.length === 0, validation_error: issues.join(' '), client_slug: 'abc-roofing', source: 'web_form', external_id: submissionId, received_at: receivedAt, name, email, phone, service, postcode, urgency, property_type: propertyType, message, honeypot, is_test: true, test_case_id: null, raw_payload: JSON.stringify(rawPayload) } }];

const x = $json;
if (!x.booking_url || /replace_me/i.test(x.booking_url)) throw new Error('Set a real booking URL in client_config before enabling email replies.');
const values = { name: x.name || 'there', service: x.service || 'your roofing request', booking_url: x.booking_url, client_name: x.client_name };
const render = (s) => String(s ?? '').replace(/{{\s*(name|service|booking_url|client_name)\s*}}/g, (_, key) => values[key]);
const subject = render(x.fallback_subject);
let body = render(x.fallback_body);
if (x.is_after_hours && x.after_hours_note) body += '\n\n' + x.after_hours_note;
const timing = { emergency: 'As soon as possible / emergency', this_week: 'This week', flexible: 'Flexible', unknown: 'Not provided' }[x.urgency] || 'Not provided';
const details = [
  `Name: ${x.name || 'Not provided'}`,
  `Email: ${x.email || 'Not provided'}`,
  `Phone: ${x.phone || 'Not provided'}`,
  `Service: ${x.service || 'Not provided'}`,
  `Postcode: ${x.postcode || 'Not provided'}`,
  `Timing: ${timing}`,
  `Property type: ${x.property_type || 'Not provided'}`,
  `Message: ${x.message || 'Not provided'}`
].join('\n');
body += '\n\nYour submitted details:\n' + details;
return [{ json: { lead_id: x.lead_id, client_id: x.client_id, to_email: x.email, from_email: x.from_name ? `${x.from_name} <${x.from_email}>` : x.from_email, reply_subject: subject, reply_body: body, reply_mode: 'fallback', score: x.score, is_after_hours: x.is_after_hours } }];
